//! `xtask deps <fn> --down|--up [--kinds k,..] [--depth N]` — who an EmuTOS
//! function depends on, and who depends on it, at the oracle pin.
//!
//! # Inputs
//!
//! Only two files, both under [`DEPS_DIR`]:
//!
//! - [`EDGES_FILE`], generated by `tools/deps/gen-deps.py` from the pinned
//!   EmuTOS build (provenance in its `#` header; never edited by hand). Rows
//!   `from to kind detail site`; kind `def` is a node row (`to` = `-`,
//!   `detail` = layer, `site` = definition), every other kind an edge.
//! - [`MAPPING_FILE`], hand-curated: EmuTOS function → NewTOS function, n:m,
//!   for the functions of EmuTOS `bios/` and `bdos/`. Rows
//!   `emutos_fn emutos_file newtos_file newtos_fn note`; `-` `-` plus a note
//!   says there is no counterpart.
//!
//! # Direction
//!
//! `--down` walks what `fn` needs to be right first, `--up` who is affected
//! when `fn` is wrong. For call-like kinds (`direct`, `table`, `callback`,
//! `asm`, `layer`, `vector`) an edge `a -> b` means `a` uses `b`: `--down`
//! follows it forward, `--up` backward. A `data` edge runs writer -> reader:
//! the reader depends on the writer, so `--down` follows it backward and
//! `--up` forward.
//!
//! # Default kinds
//!
//! `direct,table,asm,layer,vector`. `vector` is a call through a variable
//! holding a function address (`lrwabs` -> `blkdev_rwabs` via `hdv_rw`):
//! call structure, like a table slot. `callback` (an address taken: a vector
//! install, a handler handed to a driver) and `data` (shared globals) are
//! opt-in with `--kinds`: they connect nearly everything (the trap handlers
//! are installed by the boot code; `run` is read by hundreds of functions),
//! so by default they would bury the call structure.

use std::collections::{BTreeMap, BTreeSet, VecDeque};
use std::fs;
use std::path::Path;

/// The generated edge list.
pub const EDGES_FILE: &str = "docs/analysis/deps/edges.tsv";
/// The hand-curated EmuTOS → NewTOS mapping.
pub const MAPPING_FILE: &str = "docs/analysis/deps/mapping.tsv";
/// Every edge kind `edges.tsv` may carry (besides the node kind `def`).
pub const KINDS: [&str; 7] = ["direct", "table", "callback", "asm", "layer", "vector", "data"];
/// The kinds a query follows unless `--kinds` says otherwise.
pub const DEFAULT_KINDS: [&str; 5] = ["direct", "table", "asm", "layer", "vector"];
/// NewTOS code a mapping row may name.
pub const NEWTOS_ROOTS: [&str; 2] = ["tos-api/src/", "kernel/src/"];
/// The EmuTOS directories the mapping covers.
pub const MAPPED_DIRS: [&str; 2] = ["bios/", "bdos/"];

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Edge {
    pub from: String,
    pub to: String,
    pub kind: String,
    pub detail: String,
    pub site: String,
}

#[derive(Default, Debug)]
pub struct Graph {
    pub edges: Vec<Edge>,
    /// fn -> [(layer, site)]
    pub defs: BTreeMap<String, Vec<(String, String)>>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MapRow {
    pub line: usize,
    pub emutos_fn: String,
    pub emutos_file: String,
    pub newtos_file: String,
    pub newtos_fn: String,
    pub note: String,
}

pub fn parse_edges(text: &str) -> Result<Graph, String> {
    let mut g = Graph::default();
    for (n, line) in text.lines().enumerate() {
        if line.starts_with('#') || line.is_empty() || line.starts_with("from\t") {
            continue;
        }
        let f: Vec<&str> = line.split('\t').collect();
        if f.len() != 5 {
            return Err(format!("{EDGES_FILE}:{}: {} columns, want 5", n + 1, f.len()));
        }
        if f[2] == "def" {
            g.defs
                .entry(f[0].to_string())
                .or_default()
                .push((f[3].to_string(), f[4].to_string()));
        } else if KINDS.contains(&f[2]) {
            g.edges.push(Edge {
                from: f[0].into(),
                to: f[1].into(),
                kind: f[2].into(),
                detail: f[3].into(),
                site: f[4].into(),
            });
        } else {
            return Err(format!("{EDGES_FILE}:{}: unknown kind `{}`", n + 1, f[2]));
        }
    }
    Ok(g)
}

pub fn parse_mapping(text: &str) -> Result<Vec<MapRow>, String> {
    let mut rows = Vec::new();
    for (n, line) in text.lines().enumerate() {
        if line.starts_with('#') || line.is_empty() || line.starts_with("emutos_fn\t") {
            continue;
        }
        let f: Vec<&str> = line.split('\t').collect();
        if f.len() != 5 {
            return Err(format!("{MAPPING_FILE}:{}: {} columns, want 5", n + 1, f.len()));
        }
        rows.push(MapRow {
            line: n + 1,
            emutos_fn: f[0].into(),
            emutos_file: f[1].into(),
            newtos_file: f[2].into(),
            newtos_fn: f[3].into(),
            note: f[4].into(),
        });
    }
    Ok(rows)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Dir {
    Down,
    Up,
}

/// One reached function: its distance and the edge it was reached over.
#[derive(Clone, Debug)]
pub struct Reached {
    pub depth: usize,
    pub via: Option<Edge>,
}

/// Breadth-first closure of `start` over `kinds` in direction `dir`.
pub fn closure(
    g: &Graph,
    start: &str,
    dir: Dir,
    kinds: &BTreeSet<String>,
    max_depth: Option<usize>,
) -> BTreeMap<String, Reached> {
    // neighbours: node -> [(next, edge)]
    let mut adj: BTreeMap<&str, Vec<(&str, &Edge)>> = BTreeMap::new();
    for e in &g.edges {
        if !kinds.contains(&e.kind) {
            continue;
        }
        let forward = (dir == Dir::Down) != (e.kind == "data");
        let (a, b) = if forward { (&e.from, &e.to) } else { (&e.to, &e.from) };
        adj.entry(a.as_str()).or_default().push((b.as_str(), e));
    }
    let mut seen: BTreeMap<String, Reached> = BTreeMap::new();
    seen.insert(start.to_string(), Reached { depth: 0, via: None });
    let mut q = VecDeque::from([start.to_string()]);
    while let Some(x) = q.pop_front() {
        let d = seen[&x].depth;
        if max_depth.is_some_and(|m| d >= m) {
            continue;
        }
        if let Some(ns) = adj.get(x.as_str()) {
            let mut ns = ns.clone();
            ns.sort_by(|a, b| (a.0, a.1).cmp(&(b.0, b.1)));
            for (n, e) in ns {
                if !seen.contains_key(n) {
                    seen.insert(n.to_string(), Reached { depth: d + 1, via: Some(e.clone()) });
                    q.push_back(n.to_string());
                }
            }
        }
    }
    seen
}

/// Every edge of `kind` with both ends in the closure, in the walk's
/// direction: the trap entries (`table`, `layer`) and vector calls
/// (`vector`) a query crosses.
pub fn crossed<'a>(
    g: &'a Graph,
    set: &BTreeMap<String, Reached>,
    kind: &str,
) -> Vec<&'a Edge> {
    let mut v: Vec<&Edge> = g
        .edges
        .iter()
        .filter(|e| e.kind == kind && set.contains_key(&e.from) && set.contains_key(&e.to))
        .collect();
    v.sort_by(|a, b| (&a.detail, &a.from, &a.to).cmp(&(&b.detail, &b.from, &b.to)));
    v
}

fn layer_of(g: &Graph, f: &str) -> String {
    match g.defs.get(f) {
        Some(d) => {
            let s: BTreeSet<&str> = d.iter().map(|(l, _)| l.as_str()).collect();
            s.into_iter().collect::<Vec<_>>().join(",")
        }
        None => "ext".into(),
    }
}

fn newtos_of(map: &[MapRow], f: &str) -> String {
    let rows: Vec<&MapRow> = map.iter().filter(|r| r.emutos_fn == f).collect();
    if rows.is_empty() {
        return String::new();
    }
    rows.iter()
        .map(|r| {
            if r.newtos_file == "-" {
                "-".to_string()
            } else {
                format!("{}@{}", r.newtos_file, r.newtos_fn)
            }
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>()
        .join(" ")
}

/// The query's report, as printed.
pub fn report(
    g: &Graph,
    map: &[MapRow],
    start: &str,
    dir: Dir,
    kinds: &BTreeSet<String>,
    max_depth: Option<usize>,
) -> Result<String, String> {
    if !g.defs.contains_key(start) && !g.edges.iter().any(|e| e.from == start || e.to == start) {
        return Err(format!("`{start}` is no node of {EDGES_FILE}"));
    }
    let set = closure(g, start, dir, kinds, max_depth);
    let dname = if dir == Dir::Down { "down" } else { "up" };
    let mut out = String::new();
    let kl: Vec<&str> = kinds.iter().map(|s| s.as_str()).collect();
    out.push_str(&format!(
        "deps {start} --{dname} (kinds {}{}): {} functions besides {start}\n",
        kl.join(","),
        max_depth.map(|d| format!(", depth {d}")).unwrap_or_default(),
        set.len() - 1
    ));
    out.push_str("depth\tfunction\tlayer\treached over\tnewtos\n");
    let mut rows: Vec<(&String, &Reached)> = set.iter().collect();
    rows.sort_by(|a, b| (a.1.depth, a.0).cmp(&(b.1.depth, b.0)));
    for (f, r) in rows {
        let via = match &r.via {
            None => "-".to_string(),
            Some(e) => {
                let d = if e.detail == "-" { String::new() } else { format!(" {}", e.detail) };
                format!("{} -> {} [{}{}]", e.from, e.to, e.kind, d)
            }
        };
        out.push_str(&format!(
            "{}\t{}\t{}\t{}\t{}\n",
            r.depth,
            f,
            layer_of(g, f),
            via,
            newtos_of(map, f)
        ));
    }
    for k in ["table", "layer", "vector"] {
        if !kinds.contains(k) {
            continue;
        }
        let c = crossed(g, &set, k);
        out.push_str(&format!("\n{k} edges inside the set ({}):\n", c.len()));
        for e in c {
            out.push_str(&format!("{}\t{} -> {}\t{}\n", e.detail, e.from, e.to, e.site));
        }
    }
    Ok(out)
}

fn parse_kinds(s: &str) -> Result<BTreeSet<String>, String> {
    if s == "all" {
        return Ok(KINDS.iter().map(|k| k.to_string()).collect());
    }
    let mut set: BTreeSet<String> = BTreeSet::new();
    let (base, list) = match s.strip_prefix('+') {
        Some(rest) => (true, rest),
        None => (false, s),
    };
    if base {
        set.extend(DEFAULT_KINDS.iter().map(|k| k.to_string()));
    }
    for k in list.split(',').filter(|k| !k.is_empty()) {
        if !KINDS.contains(&k) {
            return Err(format!("unknown kind `{k}` (kinds: {})", KINDS.join(",")));
        }
        set.insert(k.to_string());
    }
    Ok(set)
}

pub fn cmd(root: &Path, args: &[String]) -> Result<(), String> {
    if args == ["--check-mapping"] {
        let g = parse_edges(&read(root, EDGES_FILE)?)?;
        let map = parse_mapping(&read(root, MAPPING_FILE)?)?;
        let bad = check_mapping(root, &g, &map);
        for b in &bad {
            println!("{b}");
        }
        return if bad.is_empty() {
            println!("{MAPPING_FILE}: {} rows, all resolve; every bios/ and bdos/ function has a row",
                     map.len());
            Ok(())
        } else {
            Err(format!("{} mapping problems", bad.len()))
        };
    }
    let mut start: Option<String> = None;
    let mut dir: Option<Dir> = None;
    let mut kinds: BTreeSet<String> = DEFAULT_KINDS.iter().map(|k| k.to_string()).collect();
    let mut depth = None;
    let mut it = args.iter();
    while let Some(a) = it.next() {
        match a.as_str() {
            "--down" => dir = Some(Dir::Down),
            "--up" => dir = Some(Dir::Up),
            "--kinds" => kinds = parse_kinds(it.next().ok_or("--kinds needs a value")?)?,
            "--depth" => {
                let v = it.next().ok_or("--depth needs a value")?;
                depth = Some(v.parse::<usize>().map_err(|_| format!("bad --depth `{v}`"))?);
            }
            s if s.starts_with('-') => return Err(format!("deps: unknown option `{s}`")),
            s => {
                if start.replace(s.to_string()).is_some() {
                    return Err("deps: one function only".into());
                }
            }
        }
    }
    let usage = "usage: cargo xtask deps <fn> --down|--up [--kinds k,..|+k,..|all] [--depth N]\n       \
                 cargo xtask deps --check-mapping";
    let start = start.ok_or(usage)?;
    let dir = dir.ok_or(usage)?;
    let g = parse_edges(&read(root, EDGES_FILE)?)?;
    let map = parse_mapping(&read(root, MAPPING_FILE)?)?;
    print!("{}", report(&g, &map, &start, dir, &kinds, depth)?);
    Ok(())
}

fn read(root: &Path, rel: &str) -> Result<String, String> {
    fs::read_to_string(root.join(rel)).map_err(|e| format!("read {rel}: {e}"))
}

/// Does `text` define `fn <name>` (any visibility, `unsafe`, `extern`)?
pub fn defines_fn(text: &str, name: &str) -> bool {
    let pat = format!("fn {name}");
    let mut from = 0;
    while let Some(i) = text[from..].find(&pat) {
        let at = from + i;
        let before_ok = at == 0 || !is_ident_byte(text.as_bytes()[at - 1]);
        let after = text.as_bytes().get(at + pat.len()).copied();
        let after_ok = !matches!(after, Some(b) if is_ident_byte(b));
        if before_ok && after_ok {
            return true;
        }
        from = at + pat.len();
    }
    false
}

fn is_ident_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

/// Every problem of `mapping.tsv` against the graph and the NewTOS tree:
/// an EmuTOS function that is no `def` row of its file, a NewTOS file or
/// function that does not exist, a `-` row without a reason, and an EmuTOS
/// `bios/`/`bdos/` function without a row.
pub fn check_mapping(root: &Path, g: &Graph, map: &[MapRow]) -> Vec<String> {
    let mut bad = Vec::new();
    let mut covered: BTreeSet<(String, String)> = BTreeSet::new();
    let mut texts: BTreeMap<String, Option<String>> = BTreeMap::new();
    for r in map {
        let at = format!("{MAPPING_FILE}:{}", r.line);
        let def_ok = g.defs.get(&r.emutos_fn).is_some_and(|d| {
            d.iter().any(|(_, site)| site.split(':').next() == Some(r.emutos_file.as_str()))
        });
        if !def_ok {
            bad.push(format!("{at}: `{}` is not defined in {}", r.emutos_fn, r.emutos_file));
        }
        covered.insert((r.emutos_fn.clone(), r.emutos_file.clone()));
        if r.newtos_file == "-" || r.newtos_fn == "-" {
            if r.newtos_file != r.newtos_fn {
                bad.push(format!("{at}: newtos_file and newtos_fn must both be `-`"));
            }
            if r.note.trim().is_empty() || r.note == "-" {
                bad.push(format!("{at}: no counterpart needs a reason in the note"));
            }
            continue;
        }
        if !NEWTOS_ROOTS.iter().any(|p| r.newtos_file.starts_with(p)) {
            bad.push(format!("{at}: {} is not NewTOS code ({})", r.newtos_file, NEWTOS_ROOTS.join(", ")));
            continue;
        }
        let text = texts
            .entry(r.newtos_file.clone())
            .or_insert_with(|| fs::read_to_string(root.join(&r.newtos_file)).ok());
        match text {
            None => bad.push(format!("{at}: {} does not exist", r.newtos_file)),
            Some(t) => {
                if !defines_fn(t, &r.newtos_fn) {
                    bad.push(format!("{at}: {} has no `fn {}`", r.newtos_file, r.newtos_fn));
                }
            }
        }
    }
    for (f, d) in &g.defs {
        for (_, site) in d {
            let file = site.split(':').next().unwrap_or("");
            if MAPPED_DIRS.iter().any(|p| file.starts_with(p))
                && !covered.contains(&(f.clone(), file.to_string()))
            {
                bad.push(format!("{MAPPING_FILE}: no row for `{f}` ({site})"));
            }
        }
    }
    bad
}

#[cfg(test)]
mod tests {
    use super::*;

    const FIXTURE: &str = "\
# header
from\tto\tkind\tdetail\tsite
a\t-\tdef\tbdos\tbdos/a.c:1
b\t-\tdef\tbdos\tbdos/b.c:1
t\t-\tdef\tbdos\tbdos/t.c:1
a\tb\tdirect\t-\tbdos/a.c:2
d\ta\ttable\tfuncs[0x1]\tbdos/t.c:5
c\td\tlayer\ttrap #1 0x1 funcs[0x1] via trap1\taes/c.c:3
w\ta\tdata\tglob\tbdos/w.c:4
a\tcb\tcallback\taddress\tbdos/a.c:3
";

    fn kinds(k: &[&str]) -> BTreeSet<String> {
        k.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn down_follows_calls_forward_and_data_backward() {
        let g = parse_edges(FIXTURE).unwrap();
        let s = closure(&g, "a", Dir::Down, &kinds(&KINDS), None);
        let names: Vec<&str> = s.keys().map(|s| s.as_str()).collect();
        assert_eq!(names, ["a", "b", "cb", "w"]);
        assert_eq!(s["w"].via.as_ref().unwrap().kind, "data");
    }

    #[test]
    fn up_follows_calls_backward_and_data_forward() {
        let g = parse_edges(FIXTURE).unwrap();
        let s = closure(&g, "a", Dir::Up, &kinds(&KINDS), None);
        let names: Vec<&str> = s.keys().map(|s| s.as_str()).collect();
        assert_eq!(names, ["a", "c", "d"]);
        assert_eq!(s["c"].depth, 2);
        let s = closure(&g, "w", Dir::Up, &kinds(&KINDS), None);
        assert!(s.contains_key("a") && s.contains_key("c"));
    }

    #[test]
    fn default_kinds_leave_out_callback_and_data() {
        let g = parse_edges(FIXTURE).unwrap();
        let s = closure(&g, "a", Dir::Down, &kinds(&DEFAULT_KINDS), None);
        assert_eq!(s.keys().collect::<Vec<_>>(), ["a", "b"]);
        assert_eq!(parse_kinds("+data").unwrap().len(), DEFAULT_KINDS.len() + 1);
        assert!(parse_kinds("bogus").is_err());
    }

    #[test]
    fn depth_limit_and_report_lists_crossed_trap_edges() {
        let g = parse_edges(FIXTURE).unwrap();
        let s = closure(&g, "a", Dir::Up, &kinds(&DEFAULT_KINDS), Some(1));
        assert_eq!(s.keys().collect::<Vec<_>>(), ["a", "d"]);
        let r = report(&g, &[], "a", Dir::Up, &kinds(&DEFAULT_KINDS), None).unwrap();
        assert!(r.contains("funcs[0x1]\td -> a\tbdos/t.c:5"), "{r}");
        assert!(r.contains("trap #1 0x1 funcs[0x1] via trap1\tc -> d"), "{r}");
        assert!(report(&g, &[], "nope", Dir::Up, &kinds(&DEFAULT_KINDS), None).is_err());
    }

    #[test]
    fn defines_fn_matches_whole_names_only() {
        let t = "pub fn getrec(x: u8) {}\nfn get_rec2() {}\npub(crate) unsafe fn xopen<T>() {}";
        assert!(defines_fn(t, "getrec"));
        assert!(defines_fn(t, "xopen"));
        assert!(!defines_fn(t, "get"));
        assert!(!defines_fn(t, "rec2"));
    }

    fn root() -> std::path::PathBuf {
        crate::workspace_root()
    }

    fn real() -> (Graph, Vec<MapRow>) {
        let r = root();
        let g = parse_edges(&read(&r, EDGES_FILE).unwrap()).unwrap();
        let m = parse_mapping(&read(&r, MAPPING_FILE).unwrap()).unwrap();
        (g, m)
    }

    /// The exit criterion of the deps tool: `--up getrec` reaches the GEMDOS
    /// file and directory calls, over the `funcs[]` table edges out of `osif`
    /// (EmuTOS `bdos/bdosmain.c`), and the trap entry `enter` above it.
    #[test]
    fn up_getrec_reaches_the_gemdos_file_calls_over_the_osif_table() {
        let (g, _) = real();
        let s = closure(&g, "getrec", Dir::Up, &kinds(&DEFAULT_KINDS), None);
        assert!(s.contains_key("osif") && s.contains_key("enter"));
        let slots: BTreeSet<&str> = crossed(&g, &s, "table")
            .into_iter()
            .filter(|e| e.from == "osif")
            .map(|e| e.detail.as_str())
            .collect();
        // Dfree Dcreate Ddelete Dsetpath Fcreate Fopen Fclose Fread Fwrite
        // Fdelete Fseek Fattrib Pexec Fsfirst Fsnext Frename: each reaches the
        // FAT or a directory record.
        for want in [
            "funcs[0x36]", "funcs[0x39]", "funcs[0x3a]", "funcs[0x3b]", "funcs[0x3c]",
            "funcs[0x3d]", "funcs[0x3e]", "funcs[0x3f]", "funcs[0x40]", "funcs[0x41]",
            "funcs[0x42]", "funcs[0x43]", "funcs[0x4b]", "funcs[0x4e]", "funcs[0x4f]",
            "funcs[0x56]",
        ] {
            assert!(slots.contains(want), "--up getrec misses {want}: {slots:?}");
        }
        // Malloc, Mfree, Dgetdrv, Tgetdate touch no record; Fdatime only
        // marks the open file dirty (EmuTOS `xgsdtof`, bdos/fsdir.c)
        for not in ["funcs[0x48]", "funcs[0x49]", "funcs[0x19]", "funcs[0x2a]", "funcs[0x57]"] {
            assert!(!slots.contains(not), "--up getrec reaches {not}");
        }
    }

    /// The edge `from -> to` of `kind` in the real graph, if any.
    fn edge<'a>(g: &'a Graph, from: &str, to: &str, kind: &str) -> Option<&'a Edge> {
        g.edges.iter().find(|e| e.from == from && e.to == to && e.kind == kind)
    }

    /// TOOL12: the BIOS storage calls reach the block-device handlers behind
    /// the system vectors (`hdv_rw` 0x476, `hdv_bpb` 0x472, `hdv_mediach`
    /// 0x47e, installed by `blkdev_init`, EmuTOS `bios/blkdev.c`) with the
    /// default kinds, so `--down lrwabs` no longer ends at `protect_wlwwwl`.
    #[test]
    fn down_lrwabs_reaches_blkdev_rwabs_over_the_hdv_rw_vector() {
        let (g, _) = real();
        for (entry, handler, slot) in [
            ("lrwabs", "blkdev_rwabs", "via hdv_rw"),
            ("getbpb", "blkdev_getbpb", "via hdv_bpb"),
            ("mediach", "blkdev_mediach", "via hdv_mediach"),
        ] {
            let s = closure(&g, entry, Dir::Down, &kinds(&DEFAULT_KINDS), None);
            let r = s.get(handler).unwrap_or_else(|| panic!("--down {entry} misses {handler}"));
            let via = r.via.as_ref().unwrap();
            assert_eq!((via.from.as_str(), via.kind.as_str(), via.detail.as_str()),
                       (entry, "vector", slot));
        }
        let s = closure(&g, "lrwabs", Dir::Down, &kinds(&DEFAULT_KINDS), None);
        assert!(s.contains_key("blkdev_rwabs") && s.len() > 2, "{:?}", s.keys());
        // and the other way: the handler is affected by the trap entry
        let s = closure(&g, "blkdev_rwabs", Dir::Up, &kinds(&DEFAULT_KINDS), None);
        assert!(s.contains_key("lrwabs") && s.contains_key("biostrap"), "{:?}", s.keys());
    }

    /// TOOL12: an AES call is resolved per opcode through the `crysbind`
    /// switch (EmuTOS `aes/gemsuper.c`): `appl_init` (desk binding, opcode
    /// 10 = APPL_INIT via `gem_if`) reaches `ap_init`.
    #[test]
    fn aes_opcode_resolves_through_the_crysbind_switch() {
        let (g, _) = real();
        let e = edge(&g, "appl_init", "ap_init", "layer").expect("appl_init -> ap_init");
        assert_eq!(e.detail, "trap #2 0xa crysbind[0xa] via gem_if");
        let t = edge(&g, "crysbind", "ap_init", "table").expect("crysbind -> ap_init");
        assert_eq!(t.detail, "crysbind[0xa]");
        // evnt_multi sets the opcode itself (gem_if0) and calls gem directly
        let e = edge(&g, "evnt_multi", "ev_multi", "layer").expect("evnt_multi -> ev_multi");
        assert_eq!(e.detail, "trap #2 0x19 crysbind[0x19] via gem");
        let s = closure(&g, "appl_init", Dir::Down, &kinds(&DEFAULT_KINDS), None);
        assert!(s.contains_key("ap_init"));
        // the unresolved fan-out of the binding to every trap #2 handler is gone
        assert!(!g.edges.iter().any(|e| e.kind == "layer" && e.detail.contains("not resolved")));
    }

    /// TOOL12: a VDI call is resolved per opcode through `jmptb1`/`jmptb2`
    /// (EmuTOS `vdi/vdi_main.c`): `gsx_tblt` stores TEXT (8) into
    /// `contrl[0]` and calls `gsx2`; `gsx_moff` passes HIDE_CUR (123) on
    /// through the carrier `gsx_0code`.
    #[test]
    fn vdi_opcode_resolves_through_the_jmptb_tables() {
        let (g, _) = real();
        let e = edge(&g, "gsx_tblt", "vdi_v_gtext", "layer").expect("gsx_tblt -> vdi_v_gtext");
        assert_eq!(e.detail, "trap #2 0x8 jmptb1[0x8] via gsx2");
        let e = edge(&g, "gsx_moff", "vdi_v_hide_c", "layer").expect("gsx_moff -> vdi_v_hide_c");
        assert_eq!(e.detail, "trap #2 0x7b jmptb2[0x7b] via gsx_0code");
        // the opcode stored by vst_height (called first) is not issued again
        assert!(edge(&g, "gsx_tblt", "vdi_vst_height", "layer").is_none());
        let s = closure(&g, "gsx_moff", Dir::Down, &kinds(&DEFAULT_KINDS), None);
        assert!(s.contains_key("vdi_v_hide_c"));
    }

    /// Every row of `mapping.tsv` names an existing EmuTOS definition and an
    /// existing NewTOS `fn`; every EmuTOS `bios/`/`bdos/` function has a row.
    #[test]
    fn mapping_rows_exist_on_both_sides() {
        let (g, m) = real();
        let bad = check_mapping(&root(), &g, &m);
        assert!(bad.is_empty(), "{} mapping problems:\n{}", bad.len(), bad.join("\n"));
    }

    #[test]
    fn check_mapping_reports_each_kind_of_problem() {
        let g = parse_edges(FIXTURE).unwrap();
        let m = parse_mapping(
            "a\tbdos/a.c\ttos-api/src/nope.rs\tx\t-\n\
             b\tbdos/zz.c\t-\t-\t-\n",
        )
        .unwrap();
        let bad = check_mapping(&root(), &g, &m);
        let all = bad.join("\n");
        assert!(all.contains("does not exist"), "{all}");
        assert!(all.contains("is not defined in bdos/zz.c"), "{all}");
        assert!(all.contains("needs a reason"), "{all}");
        assert!(all.contains("no row for `t`"), "{all}");
    }
}
